31	const FIRST_INSURANCE_MULTIPLIER = 1.1;
32	const CONTRACT_FEE = 5;
33	
34	// Math.round only clears the float artifact in 100 × 1.1 = 110.00000000000001;
35	// no test yet lands on a half-way value, so the rounding *direction* stays
36	// unspecified until the "rounds in MHPCO's favor" test pins it.
37	const quotePremium = (item: Item): number =>
38	  Math.round(BASE_PRICE_BY_TYPE[item.type] * FIRST_INSURANCE_MULTIPLIER) + CONTRACT_FEE;
39	
40	// Every test so far quotes exactly one item per step, so the step premium is
41	// just that item's premium. Summing across items — and the building-block
42	// discount that will complicate the sum — stays unwritten until a test asks.
43	const quoteStep = (step: Step): StepResult => ({
44	  premium: quotePremium((step.items ?? [])[0]),
45	});
46	
47	export const runScenario = (scenario: Scenario): ScenarioResult => ({
48	  results: scenario.steps.map(quoteStep),
49	});
